BEGIN;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create function pg_temp.throws(statement text,label text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;perform pg_temp.check_it(failed,label);end$$;
create function pg_temp.i(n int)returns uuid language sql immutable as $$select('ee680000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create temp table st(k text primary key,v jsonb);
insert into public.organizations(id,name)values(pg_temp.i(1),'BI report fixture'),(pg_temp.i(2),'BI other tenant');
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at)select pg_temp.i(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','bi-'||n||'@fixture.invalid',clock_timestamp(),clock_timestamp(),clock_timestamp()from generate_series(101,103)n;
insert into public.profiles(id,org_id,role)select pg_temp.i(n),pg_temp.i(case when n=103 then 2 else 1 end),'viewer'from generate_series(101,103)n on conflict(id)do update set org_id=excluded.org_id,role=excluded.role;
insert into public.properties(id,org_id,name)values(pg_temp.i(201),pg_temp.i(1),'Report property'),(pg_temp.i(202),pg_temp.i(2),'Other property');
insert into public.fact_marketing_performance(id,property_id,date,channel_id,source_account_id,currency_code,campaign_id,campaign_name,impressions,clicks,spend,conversions,raw_source)select pg_temp.i(1000+n),pg_temp.i(201),'2026-08-03','google_ads','1111111111','USD','campaign-'||n,'Campaign '||n,100,2,1.01,0.125,'PRIVATE-SOURCE'from generate_series(1,1101)n;
insert into public.fact_marketing_performance(id,property_id,date,channel_id,source_account_id,currency_code,campaign_id,impressions,clicks,spend,conversions)values(pg_temp.i(999),pg_temp.i(201),'2026-08-02','meta_ads','2222222222','USD','prior',0,0,0,0);
create function pg_temp.filters()returns jsonb language sql immutable as $$select '{"startDate":"2026-08-03","endDate":"2026-08-03","compare":true,"channel":null,"account":null}'::jsonb$$;
create function pg_temp.source(f jsonb default pg_temp.filters(),a int default 101,p int default 201)returns jsonb language sql as $$select public.bi_report_source(pg_temp.i(a),pg_temp.i(p),f)$$;
create function pg_temp.save(n int,label text default'Review',a int default 101)returns jsonb language sql as $$select public.save_bi_report(pg_temp.i(n),pg_temp.i(a),pg_temp.i(201),jsonb_build_object('label',label,'filters',pg_temp.filters(),'sourceHash',pg_temp.source()->>'sourceHash'))$$;
create function pg_temp.read(kind text default'history',n int default null,a int default 101)returns jsonb language sql as $$select public.read_bi_reports(pg_temp.i(a),pg_temp.i(201),jsonb_build_object('kind',kind,'id',pg_temp.i(n)))$$;
create function pg_temp.export(n int,report int default 301,format text default'csv',a int default 101)returns jsonb language sql as $$select public.prepare_bi_export(pg_temp.i(n),pg_temp.i(a),pg_temp.i(201),pg_temp.i(report),format)$$;
grant all on assertion_count,st to service_role;
set local role service_role;
insert into st values('source',pg_temp.source());
select pg_temp.check_it((select v->>'state'='ready'and jsonb_array_length(v#>'{source,currentRows}')=1101 from st where k='source'),'complete native source beyond Data API row limit');
select pg_temp.check_it(pg_temp.source()->>'sourceHash'=(select v->>'sourceHash'from st where k='source'),'unchanged source hash stable across reads');
select pg_temp.check_it(pg_temp.source()#>>'{source,previousPeriod,start}'='2026-08-02'and jsonb_array_length(pg_temp.source()#>'{source,previousRows}')=1,'equal-length immediately preceding comparison');
select pg_temp.check_it(pg_temp.source()::text not like'%PRIVATE-SOURCE%'and pg_temp.source()::text not like'%raw_source%','raw import provenance excluded from report');
select pg_temp.check_it((pg_temp.source()#>>'{source,currentRows,0,conversions}')::numeric=0.125,'fractional attribution survives source projection');
select pg_temp.check_it(jsonb_array_length(pg_temp.source(pg_temp.filters()||'{"account":"3333333333"}')#>'{source,currentRows}')=0,'account filter stays separate');
select pg_temp.check_it(jsonb_array_length(pg_temp.source(pg_temp.filters()||'{"channel":"meta_ads"}')#>'{source,currentRows}')=0,'channel filter excludes unrelated facts');
select pg_temp.check_it(jsonb_array_length(pg_temp.source(pg_temp.filters()||'{"compare":false}')#>'{source,previousRows}')=0,'comparison off excludes prior rows');
select pg_temp.check_it(pg_temp.source(pg_temp.filters(),103)->>'state'='forbidden','cross-tenant read denied');
select pg_temp.check_it(pg_temp.source(pg_temp.filters(),101,202)->>'state'='forbidden','other property read denied');
select pg_temp.check_it(pg_temp.source(pg_temp.filters()||'{"startDate":"2026-02-30"}')->>'state'='invalid_filters','invalid calendar date rejected');
select pg_temp.check_it(pg_temp.source(pg_temp.filters()||'{"startDate":"2024-01-01"}')->>'state'='invalid_filters','oversized range rejected');
select pg_temp.check_it(pg_temp.source(pg_temp.filters()||'{"channel":123}')->>'state'='invalid_filters','invalid channel type rejected');
select pg_temp.check_it(pg_temp.source(pg_temp.filters()||'{"extra":"unexpected"}')->>'state'='invalid_filters','unknown filter rejected');
select pg_temp.check_it(pg_temp.save(301)->>'state'='saved','native report saves');
select pg_temp.check_it(pg_temp.save(301)->>'state'='replayed','lost reply exact replay');
select pg_temp.check_it(pg_temp.save(301,'Changed')->>'state'='request_conflict','same ID cannot change decision');
select pg_temp.check_it(pg_temp.save(301,'Review',102)->>'state'='not_found','other member cannot take over request identity');
select pg_temp.check_it(pg_temp.read('detail',301,102)->>'status'='saved','current property member can review saved report');
select pg_temp.check_it(pg_temp.read('detail',301,103)->>'state'='forbidden','other tenant cannot inspect report');
select pg_temp.check_it(public.cancel_bi_report(pg_temp.i(301),pg_temp.i(101),pg_temp.i(201))->>'status'='saved','cancellation does not erase completed report');
select pg_temp.check_it(public.cancel_bi_report(pg_temp.i(302),pg_temp.i(101),pg_temp.i(201))->>'status'='cancelled','unused save cancellation retained');
select pg_temp.check_it(pg_temp.save(302)->>'status'='cancelled','late save cannot cross cancellation');
select pg_temp.throws($q$update public.bi_reports set label='tampered'where id=pg_temp.i(301)$q$,'saved report immutable');
select pg_temp.throws($q$delete from public.bi_reports where id=pg_temp.i(301)$q$,'ordinary delete cannot remove saved evidence');
select pg_temp.check_it(pg_temp.export(401)->>'state'='prepared','saved export prepared');
select pg_temp.check_it(pg_temp.export(401)->>'outcome'is null,'preparation cannot claim browser receipt');
select pg_temp.check_it(pg_temp.export(401)->>'sourceHash'=(select v->>'sourceHash'from st where k='source'),'export uses exact saved fingerprint');
select pg_temp.check_it(pg_temp.export(401,301,'pdf')->>'state'='request_conflict','export ID binds format');
select pg_temp.check_it(pg_temp.export(401,301,'csv',102)->>'state'='not_found','another member cannot take over export');
select pg_temp.check_it(pg_temp.export(402,302)->>'state'='not_found','cancelled report cannot export');
select pg_temp.check_it(public.report_bi_export(pg_temp.i(401),pg_temp.i(102),pg_temp.i(201),'download_started')->>'state'='not_found','observation requires export owner');
select pg_temp.check_it(public.report_bi_export(pg_temp.i(401),pg_temp.i(101),pg_temp.i(201),'delivered')->>'state'='invalid_input','receipt cannot claim delivery');
select pg_temp.check_it(public.report_bi_export(pg_temp.i(401),pg_temp.i(101),pg_temp.i(201),'download_started')->>'state'='saved','browser observation retained');
select pg_temp.check_it(public.report_bi_export(pg_temp.i(401),pg_temp.i(101),pg_temp.i(201),'download_started')->>'state'='replayed','observation retry exact');
select pg_temp.check_it(public.report_bi_export(pg_temp.i(401),pg_temp.i(101),pg_temp.i(201),'download_failed')->>'state'='request_conflict','first browser observation immutable');
select pg_temp.check_it(pg_temp.read('export',401)->>'outcome'='download_started','lost observation reply recoverable');
select pg_temp.check_it((select count(*)=1 from public.shared_action_events where id=pg_temp.i(301)),'saved report and event exactly once');
select pg_temp.check_it((select count(*)=1 from public.shared_action_events where episode_id=pg_temp.i(401)and action='bi.export.reported'and evidence='browser_observed'and phase='observed'),'browser evidence retains weaker observation semantics');
reset role;
update public.fact_marketing_performance set spend=99 where id=pg_temp.i(1001);
set local role service_role;
select pg_temp.check_it(pg_temp.source()->>'sourceHash'<>(select v->>'sourceHash'from st where k='source'),'updated import changes current fingerprint');
select pg_temp.check_it(pg_temp.export(401)->'source'=(select v->'source'from st where k='source'),'saved report export remains unchanged after imports');
select pg_temp.check_it(public.save_bi_report(pg_temp.i(303),pg_temp.i(101),pg_temp.i(201),jsonb_build_object('label','Stale','filters',pg_temp.filters(),'sourceHash',(select v->>'sourceHash'from st where k='source')))->>'state'='source_changed','stale preview save held');
select pg_temp.check_it(not exists(select 1 from public.bi_reports where id=pg_temp.i(303)),'stale source does not create report');
select public.cancel_bi_report(pg_temp.i(n),pg_temp.i(101),pg_temp.i(201))from generate_series(500,524)n;
insert into st values('history',pg_temp.read());
select pg_temp.check_it(pg_temp.read()->>'total'='27'and jsonb_array_length(pg_temp.read()->'items')=20,'history total covers all saved decisions');
select pg_temp.check_it(jsonb_array_length(public.read_bi_reports(pg_temp.i(101),pg_temp.i(201),jsonb_build_object('kind','history','offset',20,'expectedHash',(select v->>'pageHash'from st where k='history')))->'items')=7,'stable second history page complete');
select public.cancel_bi_report(pg_temp.i(525),pg_temp.i(101),pg_temp.i(201));
select pg_temp.check_it(public.read_bi_reports(pg_temp.i(101),pg_temp.i(201),jsonb_build_object('kind','history','offset',20,'expectedHash',(select v->>'pageHash'from st where k='history')))->>'state'='history_changed','changed history holds pagination');
do $$begin for n in 600..622 loop perform pg_temp.export(n);end loop;end$$;
select pg_temp.check_it(pg_temp.read('exports',301)->>'total'='24'and jsonb_array_length(pg_temp.read('exports',301)->'items')=20,'export history is paged completely');
select pg_temp.check_it(jsonb_array_length(public.read_bi_reports(pg_temp.i(101),pg_temp.i(201),jsonb_build_object('kind','exports','id',pg_temp.i(301),'offset',20))->'items')=4,'remaining export page available');
reset role;
create function pg_temp.reject_event()returns trigger language plpgsql as $$begin if new.action like'bi.%'then raise exception 'Injected evidence failure';end if;return new;end$$;
create trigger bi_fixture_event_failure before insert on public.shared_action_events for each row execute function pg_temp.reject_event();
set local role service_role;
select pg_temp.throws($q$select pg_temp.save(304)$q$,'shared evidence failure rolls back report');
select pg_temp.throws($q$select pg_temp.export(404)$q$,'shared evidence failure rolls back export');
select pg_temp.check_it(not exists(select 1 from public.bi_reports where id=pg_temp.i(304))and not exists(select 1 from public.bi_report_exports where id=pg_temp.i(404)),'no disconnected native decision after evidence failure');
reset role;
drop trigger bi_fixture_event_failure on public.shared_action_events;
select set_config('p11.team_scope',pg_temp.i(1)::text,true);
update public.profiles set org_id=null where id=pg_temp.i(101);
set local role service_role;
select pg_temp.check_it(pg_temp.read()->>'state'='forbidden','removed membership cannot read historical reports');
select pg_temp.check_it(pg_temp.export(401)->>'state'='forbidden','removed membership cannot replay export');
select pg_temp.check_it(public.report_bi_export(pg_temp.i(600),pg_temp.i(101),pg_temp.i(201),'download_started')->>'state'='forbidden','removed membership cannot add observation');
reset role;
select pg_temp.check_it(not has_function_privilege('authenticated','public.bi_report_source(uuid,uuid,jsonb)','EXECUTE')and not has_function_privilege('anon','public.save_bi_report(uuid,uuid,uuid,jsonb)','EXECUTE'),'browser cannot forge actor IDs');
select pg_temp.check_it(not has_table_privilege('authenticated','public.bi_reports','SELECT')and not has_table_privilege('anon','public.bi_report_exports','INSERT'),'native report tables service-only');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where org_id=pg_temp.i(1)and(training_eligible or request::text like'%PRIVATE-SOURCE%')),'BI actions exclude raw data and remain training-ineligible');
select pg_temp.check_it(public.read_bi_reports(pg_temp.i(102),pg_temp.i(201),'{"kind":"history","offset":100020}')->>'state'='ready','history has no arbitrary hundred-thousand row ceiling');
select n as passed_assertions from assertion_count;
ROLLBACK;
